// The php-ext backend (docs/spec/fsm.md, B-4 and B-6; docs/plans/fsm-v1/plan.md, C-2): the generated files of the php-ext
// package `src/`, which phpize builds into one PHP extension (config.m4). It takes the IRs of the machines (normalize.mjs), in
// definition order, the lock, the php namespace and the extension name, and returns the text of every file; it writes nothing.
// The output is deterministic: declaration order, tab indentation and a final line break.
//
// The extension registers the same public API as the php kind (backends/php.mjs): the enums State and Event of each machine
// with zend_register_internal_enum (final, as a userland enum is), the namespace functions of B-6 with ZEND_NS_NAMED_FE, the final class Step, and the shared
// Fsm\Code enum and Fsm\Error exception. The machine module of key <m> is the namespace <ns>\<Pascal m>; the shared module
// is <ns>\Fsm. Each machine is one C file `<m>.c`; `fsm.c` holds the shared classes and the module entry, which calls the
// init function of every machine in definition order. `<ext>.stub.php` declares the signatures, and the arginfo `<ext>_arginfo.h` is written from it by `make php-ext-arginfo` of kit
// with the gen_stub.php of the PHP, so the C code names the arginfo that gen_stub names (arginfo_<namespace>_<function>,
// arginfo_class_<namespace>_<class>_<method>).
//
// The language-forced differences from the php kind: the functions are C functions that read the backing value of an enum case
// (its code, or its event index) and return the case object of a value with zend_enum_get_case_by_value, so no state is stored
// in C; the error messages are the ones of the php kind, and the Error fields are the same ints. The php package's PHPUnit files
// test either implementation, so the php-ext package holds no test.

import { SHARED, header, pascal, text } from './common.mjs';

const NAMESPACE = /^[A-Za-z][A-Za-z0-9]*(\\[A-Za-z][A-Za-z0-9]*)*$/;
const EXTENSION = /^[a-z][a-z0-9_]*$/;

/** A PHP name or a C text, escaped for a C string literal or for a macro argument that is stringified (backslashes doubled). */
const cText = value => value.replace(/\\/g, '\\\\').replace(/"/g, '\\"');

/** A C string literal of `value`. */
const cLiteral = value => `"${cText(value)}"`;

/** The php namespace of the generated files, which must be given; anything else is an Error, so nothing is written. */
function checkedNamespace(phpNamespace) {
  if (typeof phpNamespace !== 'string' || !NAMESPACE.test(phpNamespace)) {
    throw new Error(`php-ext: the php namespace must be letters and digits separated by single backslashes, such as Polyspec\\FsmTest; it is ${JSON.stringify(phpNamespace)}`);
  }
  return phpNamespace;
}

/** The extension name, which names the C module, the header and the stub: lowercase letters, digits and underscores. */
function checkedExtension(phpExtName) {
  if (typeof phpExtName !== 'string' || !EXTENSION.test(phpExtName)) {
    throw new Error(`php-ext: the php extension name must be lowercase letters, digits and underscores, starting with a letter, such as polyspec_fsm; it is ${JSON.stringify(phpExtName)}`);
  }
  return phpExtName;
}

/** The IR facts of one machine that the C code and the stub need. */
function describe(ir, phpNs) {
  const { machine, states, events, transitions } = ir;
  return {
    machine,
    ns: `${phpNs}\\${pascal(machine)}`,
    states,
    events,
    stateCode: key => states.find(state => state.key === key).code,
    eventIndex: key => events.findIndex(event => event.key === key) + 1,
    outgoing: state => events.filter(event => transitions.some(item => item.state === state.key && item.event === event.key)),
    to: (state, event) => transitions.find(item => item.state === state && item.event === event).to,
  };
}

/** The C code of one machine: the enums State and Event, the class Step, the namespace functions and the init function. */
function machineC(ir, phpNs, ext, reserved) {
  const d = describe(ir, phpNs);
  const { machine, initial, states, events } = ir;
  const stateName = `${d.ns}\\State`;
  const eventName = `${d.ns}\\Event`;
  const token = d.ns.replace(/\\/g, '_');
  const p = machine;
  const reservedCodes = [...reserved].sort((a, b) => a - b);
  const noState = [
    '\t\tdefault:',
    `\t\t\t${p}_no_state(code);`,
    '\t\t\tRETURN_THROWS();',
  ];
  const lines = [
    `// Code generated by fsm-gen from ${machine}; DO NOT EDIT.`,
    '#ifdef HAVE_CONFIG_H',
    '# include "config.h"',
    '#endif',
    '',
    `#include "php_${ext}.h"`,
    `#include "${ext}_arginfo.h"`,
    '',
    `static zend_class_entry *${p}_state_ce;`,
    `static zend_class_entry *${p}_event_ce;`,
    `static zend_class_entry *${p}_step_ce;`,
    '',
    '/* The case object of a state code, or NULL with an exception pending when no state has the code. */',
    `static zend_object *${p}_state_case(zend_long code)`,
    '{',
    '\tzend_object *state = NULL;',
    '',
    `\tzend_enum_get_case_by_value(&state, ${p}_state_ce, code, NULL, false);`,
    '\treturn state;',
    '}',
    '',
    '/* The case object of an event index (its declaration index from 1), or NULL with an exception pending. */',
    `static zend_object *${p}_event_case(zend_long index)`,
    '{',
    '\tzend_object *event = NULL;',
    '',
    `\tzend_enum_get_case_by_value(&event, ${p}_event_ce, index, NULL, false);`,
    '\treturn event;',
    '}',
    '',
    '/* The code of a state object: the backing value of its case. */',
    `static zend_long ${p}_state_code(zend_object *state)`,
    '{',
    '\tzval rv;',
    '',
    `\treturn Z_LVAL_P(zend_read_property(${p}_state_ce, state, "value", sizeof("value") - 1, 1, &rv));`,
    '}',
    '',
    '/* The index of an event object: the backing value of its case. */',
    `static zend_long ${p}_event_index(zend_object *event)`,
    '{',
    '\tzval rv;',
    '',
    `\treturn Z_LVAL_P(zend_read_property(${p}_event_ce, event, "value", sizeof("value") - 1, 1, &rv));`,
    '}',
    '',
    '/* Leaves the E_UNKNOWN_CODE of a code that is no state of the machine pending. */',
    `static void ${p}_no_state(zend_long code)`,
    '{',
    `\tzend_string *message = zend_strpprintf(0, "${machine}: " ZEND_LONG_FMT " is not a state of ${machine}", code);`,
    '',
    '\tfsm_throw("E_UNKNOWN_CODE", message, NULL, NULL, NULL);',
    '\tzend_string_release(message);',
    '}',
    '',
    '/* Returns the state of a code in return_value; a code that is no state leaves an exception pending. */',
    `static void ${p}_return_state(zval *return_value, zend_long code)`,
    '{',
    `\tzend_object *state = ${p}_state_case(code);`,
    '',
    '\tif (state == NULL) {',
    '\t\tRETURN_THROWS();',
    '\t}',
    '\tRETURN_OBJ_COPY(state);',
    '}',
    '',
    '/* Appends the case of an event index to the list; a missing case leaves an exception pending. */',
    `static void ${p}_push_event(zval *list, zend_long index)`,
    '{',
    `\tzend_object *event = ${p}_event_case(index);`,
    '\tzval item;',
    '',
    '\tif (event == NULL) {',
    '\t\treturn;',
    '\t}',
    '\tZVAL_OBJ_COPY(&item, event);',
    '\tzend_hash_next_index_insert(Z_ARRVAL_P(list), &item);',
    '}',
    '',
    '/* Sets the fields of a Step: the state that the event leads to and whether the stored state changed. */',
    `static void ${p}_step_init(zend_object *step, zend_object *to, bool changed)`,
    '{',
    '\tzval state, flag;',
    '',
    '\tZVAL_OBJ(&state, to);',
    '\tZVAL_BOOL(&flag, changed);',
    `\tzend_update_property(${p}_step_ce, step, "to", sizeof("to") - 1, &state);`,
    `\tzend_update_property(${p}_step_ce, step, "changed", sizeof("changed") - 1, &flag);`,
    '}',
    '',
    '/* Returns a new Step in return_value for the state of code to; a code that is no state leaves an exception pending. */',
    `static void ${p}_return_step(zval *return_value, zend_long to, bool changed)`,
    '{',
    `\tzend_object *state = ${p}_state_case(to);`,
    '',
    '\tif (state == NULL) {',
    '\t\tRETURN_THROWS();',
    '\t}',
    `\tobject_init_ex(return_value, ${p}_step_ce);`,
    `\t${p}_step_init(Z_OBJ_P(return_value), state, changed);`,
    '}',
    '',
    `/* The state that the event index leads to from the expected code (docs/spec/fsm.md, B-6). 0 is no state: an`,
    ' * E_INVALID_TRANSITION is then pending. */',
    `static zend_long ${p}_target(zend_long expected, zend_long event)`,
    '{',
    '\tswitch (expected) {',
  ];
  for (const state of states) {
    const edges = d.outgoing(state);
    lines.push(`\t\tcase ${state.code}:`);
    if (edges.length > 0) {
      lines.push('\t\t\tswitch (event) {');
      for (const edge of edges) {
        lines.push(`\t\t\t\tcase ${d.eventIndex(edge.key)}:`, `\t\t\t\t\treturn ${d.stateCode(d.to(state.key, edge.key))};`);
      }
      lines.push('\t\t\t\tdefault:', '\t\t\t\t\tbreak;', '\t\t\t}', '\t\t\tbreak;');
    } else {
      lines.push('\t\t\tbreak;');
    }
  }
  lines.push(
    '\t\tdefault:',
    '\t\t\tbreak;',
    '\t}',
    '\tzval expected_value, event_value;',
    '\tzend_string *message;',
    '',
    '\tZVAL_LONG(&expected_value, expected);',
    '\tZVAL_LONG(&event_value, event);',
    `\tmessage = zend_strpprintf(0, "${machine}: the event " ZEND_LONG_FMT " has no edge from " ZEND_LONG_FMT, event, expected);`,
    '\tfsm_throw("E_INVALID_TRANSITION", message, &expected_value, NULL, &event_value);',
    '\tzend_string_release(message);',
    '\treturn 0;',
    '}',
    '',
  );
  // The namespace functions, in the order of the php kind's functions.php.
  lines.push(
    `/* ${machine}: the initial state. */`,
    `ZEND_NAMED_FUNCTION(zif_${p}_initial)`,
    '{',
    '\tZEND_PARSE_PARAMETERS_NONE();',
    `\t${p}_return_state(return_value, ${d.stateCode(initial)});`,
    '}',
    '',
    `ZEND_NAMED_FUNCTION(zif_${p}_code)`,
    '{',
    '\tzval *state;',
    '',
    '\tZEND_PARSE_PARAMETERS_START(1, 1)',
    `\t\tZ_PARAM_OBJECT_OF_CLASS(state, ${p}_state_ce)`,
    '\tZEND_PARSE_PARAMETERS_END();',
    `\tRETURN_LONG(${p}_state_code(Z_OBJ_P(state)));`,
    '}',
    '',
    `ZEND_NAMED_FUNCTION(zif_${p}_key)`,
    '{',
    '\tzval *state;',
    '',
    '\tZEND_PARSE_PARAMETERS_START(1, 1)',
    `\t\tZ_PARAM_OBJECT_OF_CLASS(state, ${p}_state_ce)`,
    '\tZEND_PARSE_PARAMETERS_END();',
    `\tzend_long code = ${p}_state_code(Z_OBJ_P(state));`,
    '',
    '\tswitch (code) {',
    ...states.flatMap(item => [`\t\tcase ${item.code}:`, `\t\t\tRETURN_STRING(${cLiteral(item.key)});`]),
    ...noState,
    '\t}',
    '}',
    '',
    `ZEND_NAMED_FUNCTION(zif_${p}_from_code)`,
    '{',
    '\tzval *input;',
    '',
    '\tZEND_PARSE_PARAMETERS_START(1, 1)',
    '\t\tZ_PARAM_ZVAL(input)',
    '\tZEND_PARSE_PARAMETERS_END();',
    '\t/* A value that is not an int is refused here: the coercion of a caller without strict_types must not convert it (B-6). */',
    '\tif (Z_TYPE_P(input) != IS_LONG) {',
    `\t\tzend_string *message = zend_strpprintf(0, "${machine}: a value of type %s is not a state of ${machine}", zend_zval_type_name(input));`,
    '',
    '\t\tfsm_throw("E_UNKNOWN_CODE", message, NULL, NULL, NULL);',
    '\t\tzend_string_release(message);',
    '\t\tRETURN_THROWS();',
    '\t}',
    '\tzend_long value = Z_LVAL_P(input);',
    '',
    '\tswitch (value) {',
    ...states.flatMap(item => [`\t\tcase ${item.code}:`, `\t\t\t${p}_return_state(return_value, ${item.code});`, '\t\t\treturn;']),
    ...reservedCodes.flatMap(code => [
      `\t\tcase ${code}:`,
      `\t\t\tfsm_throw_text("E_RESERVED_CODE", ${cLiteral(`${machine}: code ${code} is reserved and is no state of ${machine}`)});`,
      '\t\t\tRETURN_THROWS();',
    ]),
    '\t\tdefault: {',
    `\t\t\tzend_string *message = zend_strpprintf(0, "${machine}: " ZEND_LONG_FMT " is not a state of ${machine}", value);`,
    '',
    '\t\t\tfsm_throw("E_UNKNOWN_CODE", message, NULL, NULL, NULL);',
    '\t\t\tzend_string_release(message);',
    '\t\t\tRETURN_THROWS();',
    '\t\t}',
    '\t}',
    '}',
    '',
    `ZEND_NAMED_FUNCTION(zif_${p}_is_final)`,
    '{',
    '\tzval *state;',
    '',
    '\tZEND_PARSE_PARAMETERS_START(1, 1)',
    `\t\tZ_PARAM_OBJECT_OF_CLASS(state, ${p}_state_ce)`,
    '\tZEND_PARSE_PARAMETERS_END();',
    `\tzend_long code = ${p}_state_code(Z_OBJ_P(state));`,
    '',
    '\tswitch (code) {',
    ...states.flatMap(item => [`\t\tcase ${item.code}:`, `\t\t\t${item.final === true ? 'RETURN_TRUE' : 'RETURN_FALSE'};`]),
    ...noState,
    '\t}',
    '}',
    '',
    `ZEND_NAMED_FUNCTION(zif_${p}_events_from)`,
    '{',
    '\tzval *state;',
    '',
    '\tZEND_PARSE_PARAMETERS_START(1, 1)',
    `\t\tZ_PARAM_OBJECT_OF_CLASS(state, ${p}_state_ce)`,
    '\tZEND_PARSE_PARAMETERS_END();',
    `\tzend_long code = ${p}_state_code(Z_OBJ_P(state));`,
    '',
    '\tswitch (code) {',
    ...states.flatMap(item => [
      `\t\tcase ${item.code}:`,
      '\t\t\tarray_init(return_value);',
      ...d.outgoing(item).map(event => `\t\t\t${p}_push_event(return_value, ${d.eventIndex(event.key)});`),
      '\t\t\treturn;',
    ]),
    ...noState,
    '\t}',
    '}',
    '',
    `ZEND_NAMED_FUNCTION(zif_${p}_target)`,
    '{',
    '\tzval *expected, *event;',
    '',
    '\tZEND_PARSE_PARAMETERS_START(2, 2)',
    `\t\tZ_PARAM_OBJECT_OF_CLASS(expected, ${p}_state_ce)`,
    `\t\tZ_PARAM_OBJECT_OF_CLASS(event, ${p}_event_ce)`,
    '\tZEND_PARSE_PARAMETERS_END();',
    `\tzend_long to = ${p}_target(${p}_state_code(Z_OBJ_P(expected)), ${p}_event_index(Z_OBJ_P(event)));`,
    '',
    '\tif (to == 0) {',
    '\t\tRETURN_THROWS();',
    '\t}',
    `\t${p}_return_state(return_value, to);`,
    '}',
    '',
    `ZEND_NAMED_FUNCTION(zif_${p}_apply)`,
    '{',
    '\tzval *expected, *event, *actual;',
    '',
    '\tZEND_PARSE_PARAMETERS_START(3, 3)',
    `\t\tZ_PARAM_OBJECT_OF_CLASS(expected, ${p}_state_ce)`,
    `\t\tZ_PARAM_OBJECT_OF_CLASS(event, ${p}_event_ce)`,
    `\t\tZ_PARAM_OBJECT_OF_CLASS(actual, ${p}_state_ce)`,
    '\tZEND_PARSE_PARAMETERS_END();',
    `\tzend_long expected_code = ${p}_state_code(Z_OBJ_P(expected));`,
    `\tzend_long event_index = ${p}_event_index(Z_OBJ_P(event));`,
    `\tzend_long actual_code = ${p}_state_code(Z_OBJ_P(actual));`,
    `\tzend_long to = ${p}_target(expected_code, event_index);`,
    '\tzval expected_value, actual_value, event_value;',
    '\tzend_string *message;',
    '',
    '\tif (to == 0) {',
    '\t\tRETURN_THROWS();',
    '\t}',
    '\tif (actual_code == expected_code) {',
    `\t\t${p}_return_step(return_value, to, true);`,
    '\t\treturn;',
    '\t}',
    '\tif (actual_code == to) {',
    `\t\t${p}_return_step(return_value, to, false);`,
    '\t\treturn;',
    '\t}',
    '\tZVAL_LONG(&expected_value, expected_code);',
    '\tZVAL_LONG(&actual_value, actual_code);',
    '\tZVAL_LONG(&event_value, event_index);',
    `\tmessage = zend_strpprintf(0, "${machine}: the stored state " ZEND_LONG_FMT " is neither " ZEND_LONG_FMT " nor " ZEND_LONG_FMT, actual_code, expected_code, to);`,
    '\tfsm_throw("E_CONFLICT", message, &expected_value, &actual_value, &event_value);',
    '\tzend_string_release(message);',
    '\tRETURN_THROWS();',
    '}',
    '',
    `ZEND_METHOD(${token}_Step, __construct)`,
    '{',
    '\tzval *to;',
    '\tbool changed;',
    '',
    '\tZEND_PARSE_PARAMETERS_START(2, 2)',
    `\t\tZ_PARAM_OBJECT_OF_CLASS(to, ${p}_state_ce)`,
    '\t\tZ_PARAM_BOOL(changed)',
    '\tZEND_PARSE_PARAMETERS_END();',
    `\t${p}_step_init(Z_OBJ_P(ZEND_THIS), Z_OBJ_P(to), changed);`,
    '}',
    '',
  );
  // The function tables and the registration of the machine.
  lines.push(
    `static const zend_function_entry ${p}_state_methods[] = {`,
    '\tZEND_FE_END',
    '};',
    '',
    `static const zend_function_entry ${p}_event_methods[] = {`,
    '\tZEND_FE_END',
    '};',
    '',
    `static const zend_function_entry ${p}_step_methods[] = {`,
    `\tZEND_ME(${token}_Step, __construct, arginfo_class_${token}_Step___construct, ZEND_ACC_PUBLIC)`,
    '\tZEND_FE_END',
    '};',
    '',
    `static const zend_function_entry ${p}_functions[] = {`,
    ...[
      ['initial', 'initial'], ['code', 'code'], ['key', 'key'], ['fromCode', 'from_code'],
      ['isFinal', 'is_final'], ['eventsFrom', 'events_from'], ['target', 'target'], ['apply', 'apply'],
    ].map(([php, c]) => `\tZEND_NS_NAMED_FE(${cLiteral(d.ns)}, ${php}, zif_${p}_${c}, arginfo_${token}_${php})`),
    '\tZEND_FE_END',
    '};',
    '',
    `zend_result ${p}_minit(void)`,
    '{',
    '\tzend_class_entry ce;',
    '\tzval value;',
    '\tzval undef;',
    `\tzend_string *state_name = zend_string_init_interned(${cLiteral(stateName)}, sizeof(${cLiteral(stateName)}) - 1, 1);`,
    '',
    `\t${p}_state_ce = zend_register_internal_enum(${cLiteral(stateName)}, IS_LONG, ${p}_state_methods);`,
    `\t${p}_state_ce->ce_flags |= ZEND_ACC_FINAL;`,
    ...states.flatMap(state => [`\tZVAL_LONG(&value, ${state.code});`, `\tzend_enum_add_case_cstr(${p}_state_ce, ${cLiteral(pascal(state.key))}, &value);`]),
    '',
    `\t${p}_event_ce = zend_register_internal_enum(${cLiteral(eventName)}, IS_LONG, ${p}_event_methods);`,
    `\t${p}_event_ce->ce_flags |= ZEND_ACC_FINAL;`,
    ...events.flatMap((event, index) => [`\tZVAL_LONG(&value, ${index + 1});`, `\tzend_enum_add_case_cstr(${p}_event_ce, ${cLiteral(pascal(event.key))}, &value);`]),
    '',
    `\tINIT_NS_CLASS_ENTRY(ce, ${cLiteral(d.ns)}, "Step", ${p}_step_methods);`,
    `\t${p}_step_ce = zend_register_internal_class(&ce);`,
    `\t${p}_step_ce->ce_flags |= ZEND_ACC_FINAL;`,
    '\tZVAL_UNDEF(&undef);',
    `\tzend_declare_typed_property(${p}_step_ce, zend_string_init("to", sizeof("to") - 1, 1), &undef, ZEND_ACC_PUBLIC | ZEND_ACC_READONLY, NULL, (zend_type) ZEND_TYPE_INIT_CLASS(state_name, 0, 0));`,
    `\tzend_declare_typed_property(${p}_step_ce, zend_string_init("changed", sizeof("changed") - 1, 1), &undef, ZEND_ACC_PUBLIC | ZEND_ACC_READONLY, NULL, (zend_type) ZEND_TYPE_INIT_MASK(MAY_BE_BOOL));`,
    '',
    `\treturn zend_register_functions(NULL, ${p}_functions, NULL, MODULE_PERSISTENT);`,
    '}',
  );
  return text(lines);
}

/** The shared module file fsm.c: the enum Fsm\Code, the exception Fsm\Error, the module entry and the init order. */
function fsmC(phpNs, ext, machines) {
  const ns = `${phpNs}\\${pascal(SHARED)}`;
  // The C symbol of the Error class: the namespace with its backslashes as underscores, then Fsm_Error (such as Acme_Tool_Fsm_Error).
  const errorClass = `${phpNs.replace(/\\/g, '_')}_Fsm_Error`;
  const codes = [['Conflict', 'E_CONFLICT'], ['InvalidTransition', 'E_INVALID_TRANSITION'], ['UnknownCode', 'E_UNKNOWN_CODE'], ['ReservedCode', 'E_RESERVED_CODE']];
  const lines = [
    `// Code generated by fsm-gen from ${SHARED}; DO NOT EDIT.`,
    '#ifdef HAVE_CONFIG_H',
    '# include "config.h"',
    '#endif',
    '',
    `#include "php_${ext}.h"`,
    `#include "${ext}_arginfo.h"`,
    '',
    '#include <string.h>',
    '',
    `zend_class_entry *fsm_code_ce;`,
    'static zend_class_entry *fsm_error_ce;',
    '',
    'static const zend_function_entry fsm_code_methods[] = {',
    '\tZEND_FE_END',
    '};',
    '',
    '/* A nullable int of the Error: NULL is the null of the property. */',
    'static zval *fsm_long_or_null(zval *item, bool is_null, zend_long value)',
    '{',
    '\tif (is_null) {',
    '\t\tZVAL_NULL(item);',
    '\t} else {',
    '\t\tZVAL_LONG(item, value);',
    '\t}',
    '\treturn item;',
    '}',
    '',
    '/* Sets an int property of the Error, which is declared on fsm_error_ce; NULL sets null. */',
    'static void fsm_set(zend_object *error, const char *name, size_t length, zval *value)',
    '{',
    '\tzval null;',
    '',
    '\tZVAL_NULL(&null);',
    '\tzend_update_property(fsm_error_ce, error, name, length, value != NULL ? value : &null);',
    '}',
    '',
    '/* Sets the fields of an Error: the message and the string code of Exception, then expected, actual and event. */',
    'static void fsm_error_init(zend_object *error, zval *code, zend_string *message, zval *expected, zval *actual, zval *event)',
    '{',
    '\tzend_update_property_str(zend_ce_exception, error, "message", sizeof("message") - 1, message);',
    '\tzend_update_property(zend_ce_exception, error, "code", sizeof("code") - 1, code);',
    '\tfsm_set(error, "expected", sizeof("expected") - 1, expected);',
    '\tfsm_set(error, "actual", sizeof("actual") - 1, actual);',
    '\tfsm_set(error, "event", sizeof("event") - 1, event);',
    '}',
    '',
    '/* Throws a Fsm\\Error with the code (such as E_CONFLICT), the message and the fields (NULL is null). The message is not released. */',
    'void fsm_throw(const char *code, zend_string *message, zval *expected, zval *actual, zval *event)',
    '{',
    '\tzval exception, code_value;',
    '',
    '\tobject_init_ex(&exception, fsm_error_ce);',
    '\tZVAL_STRING(&code_value, code);',
    '\tfsm_error_init(Z_OBJ(exception), &code_value, message, expected, actual, event);',
    '\tzval_ptr_dtor(&code_value);',
    '\tzend_throw_exception_object(&exception);',
    '}',
    '',
    '/* Throws a Fsm\\Error whose message is the C text. */',
    'void fsm_throw_text(const char *code, const char *message)',
    '{',
    '\tzend_string *text = zend_string_init(message, strlen(message), 0);',
    '',
    '\tfsm_throw(code, text, NULL, NULL, NULL);',
    '\tzend_string_release(text);',
    '}',
    '',
    `ZEND_METHOD(${errorClass}, __construct)`,
    '{',
    '\tzval *code;',
    '\tzend_string *message;',
    '\tzend_long expected = 0, actual = 0, event = 0;',
    '\tbool expected_is_null = true, actual_is_null = true, event_is_null = true;',
    '',
    '\tZEND_PARSE_PARAMETERS_START(2, 5)',
    '\t\tZ_PARAM_OBJECT_OF_CLASS(code, fsm_code_ce)',
    '\t\tZ_PARAM_STR(message)',
    '\t\tZ_PARAM_OPTIONAL',
    '\t\tZ_PARAM_LONG_OR_NULL(expected, expected_is_null)',
    '\t\tZ_PARAM_LONG_OR_NULL(actual, actual_is_null)',
    '\t\tZ_PARAM_LONG_OR_NULL(event, event_is_null)',
    '\tZEND_PARSE_PARAMETERS_END();',
    '',
    '\tzval rv, expected_value, actual_value, event_value;',
    '\tzval *code_value = zend_read_property(fsm_code_ce, Z_OBJ_P(code), "value", sizeof("value") - 1, 1, &rv);',
    '',
    '\tfsm_error_init(Z_OBJ_P(ZEND_THIS), code_value, message, fsm_long_or_null(&expected_value, expected_is_null, expected),',
    '\t\tfsm_long_or_null(&actual_value, actual_is_null, actual), fsm_long_or_null(&event_value, event_is_null, event));',
    '}',
    '',
    'static const zend_function_entry fsm_error_methods[] = {',
    `\tZEND_ME(${errorClass}, __construct, arginfo_class_${errorClass}___construct, ZEND_ACC_PUBLIC)`,
    '\tZEND_FE_END',
    '};',
    '',
    `zend_result ${SHARED}_minit(void)`,
    '{',
    '\tzend_class_entry ce;',
    '\tzval value;',
    '\tzval undef;',
    '',
    `\tfsm_code_ce = zend_register_internal_enum(${cLiteral(`${ns}\\Code`)}, IS_STRING, fsm_code_methods);`,
    '\tfsm_code_ce->ce_flags |= ZEND_ACC_FINAL;',
    ...codes.flatMap(([name, code]) => [
      `\tZVAL_STR(&value, zend_string_init_interned(${cLiteral(code)}, sizeof(${cLiteral(code)}) - 1, 1));`,
      `\tzend_enum_add_case_cstr(fsm_code_ce, ${cLiteral(name)}, &value);`,
    ]),
    '',
    `\tINIT_NS_CLASS_ENTRY(ce, ${cLiteral(ns)}, "Error", fsm_error_methods);`,
    '\tfsm_error_ce = zend_register_internal_class_ex(&ce, zend_ce_exception);',
    '\tfsm_error_ce->ce_flags |= ZEND_ACC_FINAL;',
    '\tZVAL_UNDEF(&undef);',
    '\tzend_declare_typed_property(fsm_error_ce, zend_string_init("expected", sizeof("expected") - 1, 1), &undef, ZEND_ACC_PUBLIC | ZEND_ACC_READONLY, NULL, (zend_type) ZEND_TYPE_INIT_MASK(MAY_BE_LONG | MAY_BE_NULL));',
    '\tzend_declare_typed_property(fsm_error_ce, zend_string_init("actual", sizeof("actual") - 1, 1), &undef, ZEND_ACC_PUBLIC | ZEND_ACC_READONLY, NULL, (zend_type) ZEND_TYPE_INIT_MASK(MAY_BE_LONG | MAY_BE_NULL));',
    '\tzend_declare_typed_property(fsm_error_ce, zend_string_init("event", sizeof("event") - 1, 1), &undef, ZEND_ACC_PUBLIC | ZEND_ACC_READONLY, NULL, (zend_type) ZEND_TYPE_INIT_MASK(MAY_BE_LONG | MAY_BE_NULL));',
    '\treturn SUCCESS;',
    '}',
    '',
    `PHP_MINIT_FUNCTION(${ext})`,
    '{',
    `\tif (${SHARED}_minit() == FAILURE) {`,
    '\t\treturn FAILURE;',
    '\t}',
    ...machines.map(machine => `\tif (${machine}_minit() == FAILURE) {\n\t\treturn FAILURE;\n\t}`),
    '\treturn SUCCESS;',
    '}',
    '',
    `zend_module_entry ${ext}_module_entry = {`,
    '\tSTANDARD_MODULE_HEADER,',
    `\t"${ext}",`,
    '\tNULL,',
    `\tPHP_MINIT(${ext}),`,
    '\tNULL,',
    '\tNULL,',
    '\tNULL,',
    '\tNULL,',
    `\tPHP_${ext.toUpperCase()}_VERSION,`,
    '\tSTANDARD_MODULE_PROPERTIES',
    '};',
    '',
    `#ifdef COMPILE_DL_${ext.toUpperCase()}`,
    '# ifdef ZTS',
    '\tZEND_TSRMLS_CACHE_DEFINE()',
    '# endif',
    `ZEND_GET_MODULE(${ext})`,
    '#endif',
  ];
  return text(lines);
}

/** The header php_<ext>.h: the module entry, the shared functions and the init function of every machine. */
function headerFile(phpNs, ext, machines) {
  const guard = `PHP_${ext.toUpperCase()}_H`;
  return text([
    header(SHARED),
    `#ifndef ${guard}`,
    `#define ${guard}`,
    '',
    '#include "php.h"',
    '#include "zend_enum.h"',
    '#include "zend_exceptions.h"',
    '',
    `#define PHP_${ext.toUpperCase()}_VERSION "1.0.0"`,
    '',
    `extern zend_module_entry ${ext}_module_entry;`,
    `#define phpext_${ext}_ptr &${ext}_module_entry`,
    '',
    'extern zend_class_entry *fsm_code_ce;',
    '',
    'zend_result fsm_minit(void);',
    'void fsm_throw(const char *code, zend_string *message, zval *expected, zval *actual, zval *event);',
    'void fsm_throw_text(const char *code, const char *message);',
    ...machines.map(machine => `zend_result ${machine}_minit(void);`),
    '',
    `#endif /* ${guard} */`,
  ]);
}

/** The stub php_<ext>.stub.php: the declarations of the namespaces, for editors and static analysis; it is never run. */
function stubFile(irs, phpNs) {
  const lines = [
    '<?php',
    '',
    header(SHARED),
    '',
    '// The declarations that the C code of this extension registers (src/*.c). They describe the API for editors and static',
    '// analysis, and they are never run: the extension itself registers the classes, enums and functions.',
    '',
  ];
  for (const ir of irs) {
    const d = describe(ir, phpNs);
    lines.push(
      `namespace ${d.ns} {`,
      '    enum State: int',
      '    {',
      ...d.states.map(state => `        case ${pascal(state.key)} = ${state.code};`),
      '    }',
      '',
      '    enum Event: int',
      '    {',
      ...d.events.map((event, index) => `        case ${pascal(event.key)} = ${index + 1};`),
      '    }',
      '',
      '    final class Step',
      '    {',
      '        public readonly State $to;',
      '        public readonly bool $changed;',
      '',
      '        public function __construct(State $to, bool $changed) {}',
      '    }',
      '',
      '    function initial(): State {}',
      '    function code(State $state): int {}',
      '    function key(State $state): string {}',
      '    function fromCode(mixed $value): State {}',
      '    function isFinal(State $state): bool {}',
      '    function eventsFrom(State $state): array {}',
      '    function target(State $expected, Event $event): State {}',
      '    function apply(State $expected, Event $event, State $actual): Step {}',
      '}',
      '',
    );
  }
  lines.push(
    `namespace ${phpNs}\\${pascal(SHARED)} {`,
    '    enum Code: string',
    '    {',
    "        case Conflict = 'E_CONFLICT';",
    "        case InvalidTransition = 'E_INVALID_TRANSITION';",
    "        case UnknownCode = 'E_UNKNOWN_CODE';",
    "        case ReservedCode = 'E_RESERVED_CODE';",
    '    }',
    '',
    '    final class Error extends \\Exception',
    '    {',
    '        public readonly ?int $expected;',
    '        public readonly ?int $actual;',
    '        public readonly ?int $event;',
    '',
    '        public function __construct(Code $code, string $message, ?int $expected = null, ?int $actual = null, ?int $event = null) {}',
    '    }',
    '}',
  );
  return text(lines);
}

/** The build declaration config.m4, read by phpize: one extension built from the fsm and machine sources. */
function configM4(irs, ext) {
  const sources = ['fsm.c', ...irs.map(ir => `${ir.machine}.c`)].join(' ');
  return text([
    `dnl Code generated by fsm-gen from ${SHARED}; DO NOT EDIT.`,
    `PHP_ARG_ENABLE([${ext.replace(/_/g, '-')}], [whether to enable ${ext}],`,
    `  [AS_HELP_STRING([--enable-${ext.replace(/_/g, '-')}], [Enable ${ext}, the fsm state machines of the fsm definitions])], [yes])`,
    '',
    `if test "$PHP_${ext.toUpperCase()}" != "no"; then`,
    `  PHP_NEW_EXTENSION([${ext}], [${sources}], [$ext_shared],, [-std=gnu11 -Wall -Wextra -Wno-unused-parameter -Wno-unused-const-variable])`,
    'fi',
  ]);
}

/**
 * The files of the php-ext package `src/` for the machines `irs` (their IRs in definition order), the lock and the options
 * { phpNamespace, phpExtName }: <machine>.c per machine, then fsm.c, the header php_<ext>.h,
 * the stub <ext>.stub.php and config.m4. Each file is { path, content }, with the path relative to src/.
 */
export function files(irs, lock, { phpNamespace, phpExtName } = {}) {
  const phpNs = checkedNamespace(phpNamespace);
  const ext = checkedExtension(phpExtName);
  const out = [];
  for (const ir of irs) {
    if (!Object.hasOwn(lock, ir.machine)) throw new Error(`php-ext: the lock has no entry for machine ${ir.machine}`);
    out.push({ path: `${ir.machine}.c`, content: machineC(ir, phpNs, ext, lock[ir.machine].reserved) });
  }
  const machines = irs.map(ir => ir.machine);
  out.push({ path: 'fsm.c', content: fsmC(phpNs, ext, machines) });
  out.push({ path: `php_${ext}.h`, content: headerFile(phpNs, ext, machines) });
  out.push({ path: `${ext}.stub.php`, content: stubFile(irs, phpNs) });
  out.push({ path: 'config.m4', content: configM4(irs, ext) });
  return out;
}
